            path.move(to: CGPoint(x: 4.25, y: 9.25))
            path.addLine(to: CGPoint(x: 12.75, y: 9.25))
            path.addQuadCurve(to: CGPoint(x: 20.25, y: 17.75), control: CGPoint(x: 20.25, y: 9.25))
        case .redo:
            path.move(to: CGPoint(x: 16.25, y: 5.25))
            path.addLine(to: CGPoint(x: 20.25, y: 9.25))
            path.addLine(to: CGPoint(x: 16.25, y: 13.25))
            path.move(to: CGPoint(x: 19.75, y: 9.25))
            path.addLine(to: CGPoint(x: 11.25, y: 9.25))
            path.addQuadCurve(to: CGPoint(x: 3.75, y: 17.75), control: CGPoint(x: 3.75, y: 9.25))
        case .timer:
            path.addEllipse(in: CGRect(x: 4.25, y: 5.25, width: 15.5, height: 15.5))
            path.move(to: CGPoint(x: 12, y: 13))
            path.addLine(to: CGPoint(x: 15.5, y: 9.5))
            path.move(to: CGPoint(x: 9, y: 2.75))
            path.addLine(to: CGPoint(x: 15, y: 2.75))
            path.move(to: CGPoint(x: 12, y: 2.75))
            path.addLine(to: CGPoint(x: 12, y: 5.25))
            path.move(to: CGPoint(x: 18, y: 5.5))
            path.addLine(to: CGPoint(x: 20, y: 7.5))
        case .document:
            path.addRoundedRect(in: CGRect(x: 4.25, y: 2.75, width: 15.5, height: 18.5), cornerSize: CGSize(width: 3, height: 3))
            path.move(to: CGPoint(x: 8, y: 8))
            path.addLine(to: CGPoint(x: 16, y: 8))
            path.move(to: CGPoint(x: 8, y: 12))
            path.addLine(to: CGPoint(x: 16, y: 12))
            path.move(to: CGPoint(x: 8, y: 16))
            path.addLine(to: CGPoint(x: 13.25, y: 16))
        case .image:
            path.addRoundedRect(in: CGRect(x: 3, y: 3.75, width: 18, height: 16.5), cornerSize: CGSize(width: 3.5, height: 3.5))
            path.addEllipse(in: CGRect(x: 6.85, y: 7.35, width: 2.8, height: 2.8))
            path.move(to: CGPoint(x: 5.5, y: 17.25))
            path.addLine(to: CGPoint(x: 10.25, y: 12.5))
            path.addLine(to: CGPoint(x: 13.25, y: 15.25))
            path.addLine(to: CGPoint(x: 15.75, y: 12.75))
            path.addLine(to: CGPoint(x: 19, y: 16.25))
        case .trim:
            path.move(to: CGPoint(x: 5, y: 3.25))
            path.addLine(to: CGPoint(x: 5, y: 16.25))
            path.addQuadCurve(to: CGPoint(x: 8, y: 19.25), control: CGPoint(x: 5, y: 19.25))
            path.addLine(to: CGPoint(x: 20.5, y: 19.25))
            path.move(to: CGPoint(x: 19, y: 20.75))
            path.addLine(to: CGPoint(x: 19, y: 7.75))
            path.addQuadCurve(to: CGPoint(x: 16, y: 4.75), control: CGPoint(x: 19, y: 4.75))
            path.addLine(to: CGPoint(x: 3.5, y: 4.75))
        }

        let scale = min(rect.width, rect.height) / 24
        let offsetX = rect.midX - 12 * scale
        let offsetY = rect.midY - 12 * scale
        return path.applying(CGAffineTransform(a: scale, b: 0, c: 0, d: scale, tx: offsetX, ty: offsetY))
    }
}
